<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Services\ResultStorageService;
use App\Core\Auth; use App\Core\Csrf; use App\Core\Database; use App\Services\SchemaUpdater; use App\Services\SmartResultImportService;
Auth::requireSuperAdmin(); $pdo=Database::connection();  $service=new SmartResultImportService($pdo); $error='';$notice='';$analysis=[];
function sriStore(array $f,string $kind):array{if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return[];if(($f['error']??0)!==UPLOAD_ERR_OK)throw new RuntimeException(ucfirst($kind).' upload failed.');$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','csv'],true))throw new RuntimeException(ucfirst($kind).' must be PDF or CSV.');if((int)$f['size']>20*1024*1024)throw new RuntimeException(ucfirst($kind).' must be 20 MB or smaller.');$safe=date('YmdHis').'-'.$kind.'-'.bin2hex(random_bytes(4)).'.'.$ext;$rel=ResultStorageService::relative($safe);$target=ResultStorageService::path($safe);if(!move_uploaded_file((string)$f['tmp_name'],$target))throw new RuntimeException('Unable to store '.$kind.' file.');return['path'=>$target,'relative'=>$rel,'url'=>ResultStorageService::publicUrl($safe),'ext'=>$ext];}
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token. Refresh and try again.');$eventId=(int)($_POST['event_id']??0);if($eventId<1)throw new RuntimeException('Select an event first.');$q=$pdo->prepare('SELECT id,name,event_date FROM bdc_events WHERE id=:id');$q->execute(['id'=>$eventId]);$event=$q->fetch();if(!$event)throw new RuntimeException('Selected event was not found.');$action=(string)($_POST['action']??'analyse');
if($action==='analyse'){$files=[];foreach(['heats','final','points']as$kind){$item=sriStore($_FILES[$kind.'_file']??[],$kind);if($item){$files[$kind]=$item;$analysis[$kind]=$service->analyse($item['path'],$kind);}}if(!$files)throw new RuntimeException('Upload at least one Heats, Final or Points file.');$token=bin2hex(random_bytes(16));$_SESSION['sri'][$token]=['event_id'=>$eventId,'files'=>$files,'analysis'=>$analysis];$_SESSION['sri_token']=$token;}
elseif($action==='commit'){$token=preg_replace('/[^a-f0-9]/','',(string)($_POST['token']??''));$s=$_SESSION['sri'][$token]??null;if(!$s||(int)$s['event_id']!==$eventId)throw new RuntimeException('Analysis expired. Upload the files again.');$replace=!empty($_POST['replace_existing']);$pdo->beginTransaction();try{$saved=0;foreach($s['files']as$kind=>$item){$cat=$kind==='final'?'finals':$kind;$old=$pdo->prepare("SELECT id FROM bdc_result_documents WHERE event_id=:e AND document_category=:c AND status='published' ORDER BY id DESC LIMIT 1");$old->execute(['e'=>$eventId,'c'=>$cat]);$id=(int)$old->fetchColumn();if($id&&!$replace)throw new RuntimeException(ucfirst($kind).' already exists for this event. Select Replace existing files.');$title=ucfirst($kind).' — '.$event['name'];if($id){$u=$pdo->prepare("UPDATE bdc_result_documents SET title=:t,file_type=:ft,url=:u,storage_path=:sp,version_number=version_number+1,source='manual_upload',updated_at=NOW() WHERE id=:id");$u->execute(['t'=>$title,'ft'=>$item['ext'],'u'=>$item['url'],'sp'=>$item['relative'],'id'=>$id]);}else{$u=$pdo->prepare("INSERT INTO bdc_result_documents(event_id,title,document_category,file_type,url,storage_path,status,source,created_by) VALUES(:e,:t,:c,:ft,:u,:sp,'published','manual_upload',:uid)");$u->execute(['e'=>$eventId,'t'=>$title,'c'=>$cat,'ft'=>$item['ext'],'u'=>$item['url'],'sp'=>$item['relative'],'uid'=>(int)Auth::user()['id']]);}$saved++;}$ps=null;if(!empty($s['files']['points'])&&!empty($s['analysis']['points']['can_import_points'])&&!empty($_POST['import_points']))$ps=$service->importPoints($s['files']['points']['path'],$eventId,(int)Auth::user()['id']);$pdo->commit();unset($_SESSION['sri'][$token],$_SESSION['sri_token']);$notice=$saved.' file(s) added to the Result Repository.'.($ps?' '.$ps['imported'].' point row(s) imported.':'');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}}}
catch(Throwable $e){$error=$e->getMessage();}
$events=$pdo->query('SELECT id,name,event_date FROM bdc_events ORDER BY event_date DESC,name')->fetchAll();$token=(string)($_SESSION['sri_token']??'');$pending=$token!==''?($_SESSION['sri'][$token]??null):null;if($pending)$analysis=$pending['analysis'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Result Import | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><span class="text-white small">Super Admin</span></div></nav><div class="container py-4" style="max-width:1200px"><div class="d-flex justify-content-between mb-4"><div><h1 class="h3 mb-1">Smart Result Import</h1><div class="text-muted">Upload Heats, Final and Points once. Files are analysed and placed in the Result Repository.</div></div><a class="btn btn-outline-secondary" href="../">Dashboard</a></div><?php if($error):?><div class="alert alert-danger" style="white-space:pre-line"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><form method="post" enctype="multipart/form-data" class="row g-3"><?=Csrf::field()?><input type="hidden" name="action" value="analyse"><div class="col-12"><label class="form-label">Event</label><select class="form-select" name="event_id" required><option value="">Select event</option><?php foreach($events as$ev):?><option value="<?=(int)$ev['id']?>"><?=e((string)$ev['event_date'].' — '.$ev['name'])?></option><?php endforeach;?></select></div><?php foreach(['heats'=>'Heats','final'=>'Final','points'=>'Points']as$k=>$label):?><div class="col-md-4"><div class="border rounded p-3 h-100"><h2 class="h5"><?=$label?></h2><input class="form-control" type="file" name="<?=$k?>_file" accept=".pdf,.csv,application/pdf,text/csv"><div class="form-text">PDF or CSV, maximum 20 MB.</div></div></div><?php endforeach;?><div class="col-12"><button class="btn btn-dark">Scan and analyse</button></div></form></div></div><?php if($pending):?><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Analysis</h2><div class="row g-3"><?php foreach($analysis as$kind=>$a):?><div class="col-md-4"><div class="border rounded p-3 h-100"><strong><?=e(ucfirst($kind))?></strong><div class="small text-muted"><?=e(strtoupper($a['format']))?>, <?=(int)$a['total_rows']?> row(s)</div><?php if($a['issues']):?><div class="alert alert-warning py-2 mt-2 mb-0"><ul class="mb-0"><?php foreach($a['issues']as$i):?><li><?=e($i)?></li><?php endforeach;?></ul><div class="small mt-2">Edit the CSV manually and upload it again for structured import.</div></div><?php else:?><div class="text-success small mt-2">Ready</div><?php endif;?></div></div><?php endforeach;?></div><form method="post" class="mt-4" onsubmit="return confirm('Publish these files to the Result Repository?')"><?=Csrf::field()?><input type="hidden" name="action" value="commit"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="event_id" value="<?=(int)$pending['event_id']?>"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="replace_existing" value="1" id="replace"><label class="form-check-label" for="replace">Replace existing files for this event</label></div><?php if(!empty($analysis['points']['can_import_points'])):?><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="import_points" value="1" id="ip" checked><label class="form-check-label" for="ip">Import structured point rows into the BDC points database</label></div><?php endif;?><button class="btn btn-success">Confirm import and publish</button></form></div></div><?php endif;?></div></body></html>
